/*
 * A319609  Numbers in base 10 that are palindromic in bases 4, 8 and 16.
 * https://oeis.org/A319609
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th number that is palindromic in bases 4, 8 and 16
 *            (OEIS A319609). The sequence is generated by enumerating all
 *            base‑4 palindromes in increasing numeric order and testing each
 *            for the other two bases
 * Range:     u8 n <= 6, u16 n <= 12, u32 n <= 31, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   append_candidate, pow4_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/append_candidate.h"
#include "../utils/pow4_uint64.h"

/* --------------------------------------------------------------------- */
/*  Check whether value x is a palindrome in the given base.  */
static bool is_pal_in_base(seq_t x, seq_t base)
{
    /* 8192 digits are enough for any seq_t that appears for the
       required n (the 10‑000‑th term has < 2000 base‑4 digits).  */
    seq_t digits[8192];
    size_t len = 0;

    if (x == (seq_t)0) {
        digits[len++] = (seq_t)0;
    } else {
        while (x != (seq_t)0) {
            digits[len++] = x % base;
            x /= base;
        }
    }

    for (size_t i = 0; i < len / 2; ++i) {
        if (digits[i] != digits[len - 1 - i])
            return false;
    }
    return true;
}

/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* Static state to keep the generated terms.  */
    static seq_t *cache        = NULL;
    static size_t cache_len    = 0;
    static size_t cache_cap    = 0;

    /* Variables that generate base‑4 palindromes in increasing order. */
    static idx_t cur_len         = 1;   /* current length of base‑4 digits  */
    static idx_t cur_index       = 0;   /* index within current length   */
    static idx_t cur_count       = 0;   /* number of candidates in len   */

    if (n < 1)          /* offset is 1, behaviour for n<1 is irrelevant */
        return (seq_t)0;

    /* Generate terms until we have at least n of them.  */
    while (cache_len < (size_t)n) {
        /* Compute the count of candidates for the current length
           whenever we start a new length.  */
        if (cur_index == 0) {
            if (cur_len == 1) {
                cur_count = 4;                     /* digits 0‑3 */
            } else {
                int halfLen = (cur_len + 1) / 2;
                uint64_t pow = pow4_uint64(halfLen - 1);
                cur_count = 3 * pow;               /* first digit 1‑3 */
            }
        }

        /* Build the base‑4 digits of the current candidate.  */
        int maxDigits = 200;                      /* enough for any n <= 10000 */
        int digits[maxDigits];

        if (cur_len == 1) {                      /* special case */
            digits[0] = (int)cur_index;          /* 0..3 */
        } else {
            int halfLen = (cur_len + 1) / 2;
            uint64_t countHalf = pow4_uint64(halfLen - 1);
            uint64_t k = cur_index;

            int first_digit = 1 + (int)(k / countHalf);
            k %= countHalf;

            digits[0] = first_digit;
            /* Remaining digits of the left half.  */
            for (int pos = halfLen - 2; pos >= 0; --pos) {
                digits[pos + 1] = (int)(k % 4);
                k /= 4;
            }
            /* Mirror the left half to form the full palindrome.  */
            for (int i = 0; i < cur_len; ++i) {
                if (i < halfLen)
                    digits[i] = digits[i];
                else
                    digits[i] = digits[cur_len - 1 - i];
            }
        }

        /* Compute the decimal value from the base‑4 digits.  */
        seq_t val = 0;
        for (int i = 0; i < (int)cur_len; ++i) {
            val = val * (seq_t)4 + (seq_t)digits[i];
        }

        /* Check the other two bases.  */
        if (is_pal_in_base(val, (seq_t)8) && is_pal_in_base(val, (seq_t)16)) {
            append_candidate(&cache, &cache_len, &cache_cap, val);
        }

        /* Advance to the next base‑4 palindrome.  */
        ++cur_index;
        if (cur_index == cur_count) {
            cur_len++;            /* move to next length */
            cur_index = 0;
            cur_count = 0;        /* will be set on next loop */
        }
    }

    return cache[n - 1];
}
